{"action":"edit","path":"toolformer_filter.py","old_text":"","new_text":"import numpy as np

def filter_api_calls(with_result, call_only, no_call, tau_filter):
    # Input validation
    for name, arr in [("with_result", with_result), ("call_only", call_only), ("no_call", no_call)]:
        if not isinstance(arr, np.ndarray):
            raise ValueError(f"{name} must be a numpy array")
        if arr.ndim != 2:
            raise ValueError(f"{name} must be a 2D matrix")
        if arr.size == 0:
            raise ValueError(f"{name} must not be empty")
        if arr.shape != with_result.shape:
            raise ValueError("Input matrices must have the same shape")
        if not np.all(np.isfinite(arr)):
            raise ValueError(f"{name} contains non-finite values")
        if np.any(arr > 0):
            raise ValueError(f"{name} contains positive values")
    if not isinstance(tau_filter, (int, float)) or isinstance(tau_filter, bool):
        raise ValueError("tau_filter must be a nonnegative numeric threshold, not boolean")
    if tau_filter < 0:
        raise ValueError("tau_filter must be nonnegative")

    n, horizon = with_result.shape
    # Weights: linear decay with offset, clip at 0, normalize
    raw_weights = np.maximum(0, 1 - 0.2 * np.arange(horizon))
    weights = raw_weights / raw_weights.sum()  # shape (horizon,)

    # Compute weighted negative log probability losses
    # Loss = - sum(weights * log_prob)
    loss_with = -np.sum(weights * with_result, axis=1)
    loss_call = -np.sum(weights * call_only, axis=1)
    loss_empty = -np.sum(weights * no_call, axis=1)

    # Stronger counterfactual: min of empty and call-only
    L_minus = np.minimum(loss_empty, loss_call)

    margins = L_minus - loss_with
    keep = margins >= tau_filter

    return keep, margins
